export default "import { AdHocVariableFilter, VariableRefresh } from '@grafana/data';\nimport {\n  SceneFlexLayout,\n  SceneVariableSet,\n  TestVariable,\n  EmbeddedScene,\n  SceneFlexItem,\n  SceneAppPage,\n  SceneAppPageState,\n  PanelBuilders,\n  SceneTimePicker,\n  VariableValueSelectors,\n  SceneRefreshPicker,\n  SceneControlsSpacer,\n  AdHocFiltersVariable,\n} from '@grafana/scenes';\nimport { VariableHide } from '@grafana/schema';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getVerticalControlsLayoutDemo(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        controls: [\n          new VariableValueSelectors({ layout: 'vertical' }),\n          new SceneControlsSpacer(),\n          new SceneTimePicker({}),\n          new SceneRefreshPicker({}),\n        ],\n        $variables: new SceneVariableSet({\n          variables: [\n            new TestVariable({\n              name: 'server',\n              query: 'A.*',\n              value: 'server',\n              text: '',\n              delayMs: 1000,\n              options: [],\n              refresh: VariableRefresh.onTimeRangeChanged,\n              description: 'Server name',\n            }),\n            new TestVariable({\n              name: 'pod',\n              query: 'A.$server.*',\n              value: 'pod',\n              delayMs: 1000,\n              isMulti: true,\n              text: '',\n              options: [],\n            }),\n            new TestVariable({\n              name: 'handler',\n              query: 'A.$server.$pod.*',\n              value: 'pod',\n              delayMs: 1000,\n              isMulti: true,\n              text: '',\n              options: [],\n              refresh: VariableRefresh.onTimeRangeChanged,\n            }),\n            new AdHocFiltersVariable({\n              name: 'filters',\n              hide: VariableHide.hideLabel,\n              layout: 'vertical',\n              applyMode: 'manual',\n              filters: [{ key: 'job', operator: '=', value: 'grafana', condition: '' }],\n              getTagKeysProvider: async (variable: AdHocFiltersVariable, currentKey: string | null) => {\n                await new Promise((resolve) => setTimeout(resolve, 200));\n                return {\n                  replace: true,\n                  values: [{ text: 'job' }, { text: 'instance' }],\n                };\n              },\n              getTagValuesProvider: async (variable: AdHocFiltersVariable, filter: AdHocVariableFilter) => {\n                await new Promise((resolve) => setTimeout(resolve, 400));\n                return {\n                  replace: true,\n                  values: ['A', 'B', 'C', 'D', 'E', 'F', 'grafana'].map((v) => ({ text: v })),\n                };\n              },\n            }),\n          ],\n        }),\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [getGraphAndTextPanel()],\n        }),\n      });\n    },\n  });\n}\n\nfunction getGraphAndTextPanel() {\n  return new SceneFlexLayout({\n    children: [\n      new SceneFlexItem({\n        body: PanelBuilders.timeseries()\n          .setTitle('handler: $handler')\n          .setData(\n            getQueryRunnerWithRandomWalkQuery({\n              alias: 'handler: $handler',\n            })\n          )\n          .build(),\n      }),\n      new SceneFlexItem({\n        body: PanelBuilders.text()\n          .setTitle('Interpolation')\n          .setOption(\n            'content',\n            `\n* server: $server\n* pod: $pod\n* handler: $handler\n\n          `\n          )\n          .build(),\n      }),\n    ],\n  });\n}\n";